<?php
defined('BASEPATH') or exit('No direct script access allowed');
class Pipeline_users extends CI_Controller {
 public function __construct(){parent::__construct();is_login();$this->load->library('Pipeline_access');$this->pipeline_access->require_menu('users');$this->load->model('Pipeline_user_model','users');if(!$this->users->ready())show_error('Jalankan migrasi pengaturan user terlebih dahulu.',503);if(!$this->session->userdata('pipeline_form_token'))$this->session->set_userdata('pipeline_form_token',bin2hex(random_bytes(24)));}
 private function guard(){if($this->input->method()!=='post')show_error('Metode tidak diizinkan.',405);$token=$this->input->post('pipeline_token');if(!is_string($token)||!hash_equals($this->session->userdata('pipeline_form_token'),$token))show_error('Form kedaluwarsa. Muat ulang halaman.',403);}
 private function version(){$v=$this->input->post('AccessVersion');if(!is_string($v)||!ctype_digit($v))throw new RuntimeException('Versi data tidak valid. Muat ulang halaman.');return (int)$v;}
 private function id($id){if(!is_string($id)||!preg_match('/^[A-Za-z0-9_.-]{1,30}$/D',$id))show_404();return $id;}
 private function actor(){return $this->session->userdata('MIS_LOGGED_ID');}
 private function render($view,$data){$data+=array('judul'=>'Pengaturan User','pipeline_token'=>$this->session->userdata('pipeline_form_token'),'roles'=>$this->user_policy->roles());$this->load->view('templates/header',$data);$this->load->view('templates/sidebar');$this->load->view('pipeline/'.$view,$data);$this->load->view('templates/footer');}
 public function index(){$q=$this->input->get('q',true);$q=is_string($q)?mb_substr(trim($q),0,100):'';$archived=$this->input->get('archived')==='1';$page=max(1,(int)$this->input->get('page'));$list=$this->users->listing($q,$archived,$page);$this->render('users',array('listing'=>$list,'search'=>$q,'archived'=>$archived,'page'=>$page,'actor'=>$this->actor()));}
 public function create(){$this->form(null);}
 public function edit($id){$this->form($this->id($id));}
 private function form($id){$creating=$id===null;$u=$creating?array('UserID'=>'','UserName'=>'','Email'=>'','UserRole'=>'OPERATOR','Active'=>'1','AccessVersion'=>0,'DeletedAt'=>null):$this->users->user($id);if(!$u||$u['DeletedAt']!==null)show_404();$error='';
  if($this->input->method()==='post'){$this->guard();$posted=$this->input->post();if(!$creating)$posted['UserID']=$id;
   try{$result=$this->users->save_profile($posted,$this->actor(),$creating?null:$this->version(),$creating);if(strcasecmp($result['UserID'],$this->actor())===0){$this->session->set_userdata('pipeline_access_version',$result['AccessVersion']);$this->session->set_userdata('MIS_LOGGED_NAME',trim($posted['UserName']));}$this->session->set_flashdata('Berhasil',$creating?'User ditambahkan. Atur menu dan area untuk mulai menggunakan aplikasi.':'Data user berhasil diperbarui.');redirect($creating?'Pipeline_users/access/'.$result['UserID']:'Pipeline_users');return;
   }catch(Exception $e){$error=$e->getMessage();foreach(array('UserID','UserName','Email','UserRole','Active') as $key)if(isset($posted[$key])&&is_string($posted[$key]))$u[$key]=$posted[$key];}
  }$this->render('user_form',array('creating'=>$creating,'user'=>$u,'error'=>$error,'actor'=>$this->actor()));
 }
 public function access($id=null){$this->pipeline_access->require_menu('access_management');if($id===null&&$this->input->get('user')!==null){$selected=$this->id($this->input->get('user'));redirect('Pipeline_users/access/'.rawurlencode($selected));return;}$error='';$id=$id===null?null:$this->id($id);$u=$id===null?null:$this->users->user($id);if($id!==null&&(!$u||$u['DeletedAt']!==null))show_404();
  if($this->input->method()==='post'){$this->guard();if(!$u)show_404();try{$areas=$this->input->post('AreaIDs');$menus=$this->input->post('MenuKeys');$this->users->save_access($id,$areas===null?array():$areas,$menus===null?array():$menus,$this->actor(),$this->version());$this->session->set_flashdata('Berhasil','Akses menu dan area disimpan. Sesi lama user akan diminta login kembali.');redirect('Pipeline_users/access/'.$id);return;}catch(Exception $e){$error=$e->getMessage();}}
  $selectedAreas=$u?$this->users->area_ids($id):array();$selectedMenus=$u?$this->users->menu_keys($id,$u['UserRole']):array();$isAdmin=$u?$this->user_policy->admin($u['UserID'],$u['UserRole']):false;
  $this->render('user_access',array('user'=>$u,'error'=>$error,'areas'=>$this->users->areas(),'selected_areas'=>$selectedAreas,'selected_menus'=>$selectedMenus,'team_access_effective'=>$u && $this->pipeline_access->allowed('customer_team',$id,$u['UserRole']),'is_admin'=>$isAdmin,'groups'=>$this->pipeline_access->groups(),'menus'=>$this->pipeline_access->menus(),'candidates'=>$this->users->listing('',false,1),'audit'=>$u?$this->users->audit($id):array(),'reserved'=>$this->user_policy->reserved()));
 }
 public function archive($id){$this->guard();try{$this->users->archive($this->id($id),$this->actor(),$this->version());$this->session->set_flashdata('Berhasil','User dihapus ke arsip dan akses login dinonaktifkan.');}catch(Exception $e){$this->session->set_flashdata('Gagal',$e->getMessage());}redirect('Pipeline_users');}
 public function restore($id){$this->guard();try{$this->users->restore($this->id($id),$this->actor(),$this->version());$this->session->set_flashdata('Berhasil','User dipulihkan dalam status nonaktif. Edit user untuk mengaktifkan kembali.');}catch(Exception $e){$this->session->set_flashdata('Gagal',$e->getMessage());}redirect('Pipeline_users?archived=1');}
}
